// GENERATED BY STUDIO (crawler v1). Studio overwrites this file before every test run.
// Walks through every screen of the app, taps everything it can find, fills in text fields with
// valid, empty and nasty values, and writes build/studio_test/report.json (+ one picture per screen).
// It runs headless with `flutter test` (no emulator needed); pictures use a plain test font.
import 'dart:convert';
import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:__PACKAGE__/main.dart' as app;

final List<Map<String, dynamic>> _screens = [];
final List<Map<String, dynamic>> _errors = [];
final Set<String> _visited = {};
Map<String, dynamic>? _current;
int _tapped = 0;
late Directory _out;

void _issue(String kind, String severity, String message, [String detail = '']) {
  final issue = {'kind': kind, 'severity': severity, 'message': message, 'detail': detail};
  if (_current != null) {
    (_current!['issues'] as List).add(issue);
  } else {
    _errors.add(issue);
  }
}

String _appBarTitle(WidgetTester t) {
  final bars = find.byType(AppBar, skipOffstage: false).evaluate();
  if (bars.isEmpty) return '';
  final bar = bars.last.widget as AppBar;
  final title = bar.title;
  return title is Text ? (title.data ?? '') : '';
}

int _depth(WidgetTester t) => find.byType(Scaffold, skipOffstage: false).evaluate().length;

String _screenId(WidgetTester t) => '${_appBarTitle(t)}@${_depth(t)}';

String _stateSig(WidgetTester t) {
  final texts = t
      .widgetList<Text>(find.byType(Text))
      .map((w) => w.data ?? w.textSpan?.toPlainText() ?? '')
      .toList();
  final switches = t.widgetList<Switch>(find.byType(Switch)).map((w) => w.value).toList();
  final checks = t.widgetList<Checkbox>(find.byType(Checkbox)).map((w) => w.value).toList();
  return '${texts.join('|')}#$switches#$checks#${t.allWidgets.length}';
}

Finder _tappables() => find.byWidgetPredicate((w) =>
    w is ElevatedButton ||
    w is FilledButton ||
    w is OutlinedButton ||
    w is TextButton ||
    w is IconButton ||
    w is FloatingActionButton ||
    w is Checkbox ||
    w is Switch ||
    w is ActionChip ||
    w is FilterChip ||
    w is ChoiceChip ||
    w is Tab ||
    w is NavigationDestination ||
    (w is ListTile && w.onTap != null));

bool _overlayShown(WidgetTester t) =>
    find.byType(AlertDialog).evaluate().isNotEmpty ||
    find.byType(SimpleDialog).evaluate().isNotEmpty ||
    find.byType(BottomSheet).evaluate().isNotEmpty ||
    find.byType(SnackBar).evaluate().isNotEmpty ||
    find.byType(PopupMenuItem).evaluate().isNotEmpty;

Future<void> _settle(WidgetTester t) async {
  await t.pump(const Duration(milliseconds: 100));
  await t.pump(const Duration(milliseconds: 400));
  await t.pump(const Duration(milliseconds: 400));
}

Future<void> _back(WidgetTester t) async {
  try {
    final nav = t.state<NavigatorState>(find.byType(Navigator).first);
    await nav.maybePop();
    await _settle(t);
  } catch (_) {}
}

Future<void> _shot(WidgetTester t, Map<String, dynamic> screen) async {
  try {
    final RenderRepaintBoundary boundary = t.renderObject(find.byType(RepaintBoundary).first);
    final name = 'screen_${_screens.length}.png';
    await t.runAsync(() async {
      final image = await boundary.toImage(pixelRatio: 1.0);
      final data = await image.toByteData(format: ui.ImageByteFormat.png);
      if (data != null) {
        await File('${_out.path}/$name').writeAsBytes(data.buffer.asUint8List());
        screen['screenshot'] = name;
      }
    });
  } catch (_) {
    // A missing picture is not a problem with the app.
  }
}

Future<void> _forms(WidgetTester t) async {
  final count = find.byType(TextField).evaluate().length;
  final values = ['Test 123', '', 'x' * 400 + ' <>"\'; 💥'];
  for (var i = 0; i < count && i < 8; i++) {
    for (final v in values) {
      final fields = find.byType(TextField);
      if (i >= fields.evaluate().length) return;
      try {
        await t.enterText(fields.at(i), v);
        await t.testTextInput.receiveAction(TextInputAction.done);
        await _settle(t);
        final ex = t.takeException();
        if (ex != null) {
          _issue('crash', 'error', 'A text field crashed with ${v.isEmpty ? 'an empty value' : 'the value "${v.length > 20 ? v.substring(0, 20) : v}…"'}', '$ex');
        }
      } catch (e) {
        _issue('crash', 'error', 'Typing in a text field failed', '$e');
      }
    }
    try {
      await t.enterText(find.byType(TextField).at(i), '');
    } catch (_) {}
  }
}

Future<void> _explore(WidgetTester t, int depth) async {
  final id = _screenId(t);
  if (_visited.contains(id) || depth > 4 || _screens.length >= 25) return;
  _visited.add(id);
  final screen = <String, dynamic>{
    'name': _appBarTitle(t).isEmpty ? 'Screen ${_screens.length + 1}' : _appBarTitle(t),
    'depth': depth,
    'taps': 0,
    'issues': <Map<String, dynamic>>[],
    'screenshot': null,
  };
  _screens.add(screen);
  final previous = _current;
  _current = screen;

  await _shot(t, screen);
  final visible = find.byType(Text).evaluate().length + find.byType(Icon).evaluate().length + find.byType(Image).evaluate().length;
  if (visible == 0) _issue('empty_screen', 'error', 'This screen shows nothing');
  await _forms(t);

  final total = _tappables().evaluate().length;
  for (var i = 0; i < total && i < 40; i++) {
    final list = _tappables();
    if (i >= list.evaluate().length) break;
    if (_screenId(t) != id) break;
    final before = _stateSig(t);
    final label = list.at(i).evaluate().first.widget.runtimeType.toString();
    try {
      await t.tap(list.at(i), warnIfMissed: false);
    } catch (e) {
      _issue('crash', 'error', 'Tapping a $label failed', '$e');
      continue;
    }
    await _settle(t);
    _tapped++;
    screen['taps'] = (screen['taps'] as int) + 1;
    final ex = t.takeException();
    if (ex != null) _issue('crash', 'error', 'Tapping a $label caused an error', '$ex');

    if (_screenId(t) != id) {
      await _explore(t, depth + 1);
      _current = screen;
      await _back(t);
      if (_screenId(t) != id) break;
    } else if (_stateSig(t) == before && !_overlayShown(t) && ex == null) {
      _issue('dead_button', 'warning', 'A $label seems to do nothing');
    }
    if (_overlayShown(t)) {
      await _back(t);
    }
  }
  _current = previous;
}

void main() {
  testWidgets('Studio crawl', (tester) async {
    _out = Directory('build/studio_test')..createSync(recursive: true);
    for (final f in _out.listSync()) {
      if (f is File && (f.path.endsWith('.png') || f.path.endsWith('report.json'))) f.deleteSync();
    }
    final started = DateTime.now();
    final originalOnError = FlutterError.onError;
    addTearDown(() => FlutterError.onError = originalOnError);
    FlutterError.onError = (details) {
      final msg = details.exceptionAsString().split('\n').first;
      final overflow = msg.contains('overflowed');
      _issue(overflow ? 'overflow' : 'crash', 'error', msg, details.context?.toDescription() ?? '');
    };

    var startedOk = true;
    try {
      app.main();
      await tester.pump(const Duration(milliseconds: 500));
      await tester.pump(const Duration(seconds: 1));
    } catch (e) {
      startedOk = false;
      _issue('crash', 'error', 'The app could not start', '$e');
    }
    if (startedOk) {
      try {
        await _explore(tester, 0);
      } catch (e) {
        _issue('crash', 'error', 'The test crawler stopped unexpectedly', '$e');
      }
    }
    final report = {
      'crawler': 1,
      'startedOk': startedOk,
      'tapped': _tapped,
      'durationMs': DateTime.now().difference(started).inMilliseconds,
      'screens': _screens,
      'errors': _errors,
    };
    File('${_out.path}/report.json').writeAsStringSync(jsonEncode(report));
    try {
      await tester.pumpWidget(const SizedBox());
    } catch (_) {}
  }, timeout: const Timeout(Duration(minutes: 5)));
}
